with enriched as (select id, customer_id, account_type, balance, opened_date, status, avg(balance) over (partition by customer_id, status order by opened_date, id rows between 6 preceding and 1 preceding) as balance_avg_6_prior, avg(balance) over (order by balance, id rows between 3 preceding and current row) as balance_avg_3, last_value(status, true) over (partition by status order by balance, id rows between unbounded preceding and current row) as last_known_status from accounts) select id, customer_id, account_type, balance, status, balance_avg_3, last_known_status from enriched order by id desc nulls first;
